PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE call_records (
	id INTEGER NOT NULL, 
	call_sid VARCHAR(100) NOT NULL, 
	agent_id INTEGER NOT NULL, 
	caller_number VARCHAR(20), 
	status VARCHAR(50), 
	recording_url VARCHAR(500), 
	duration INTEGER, 
	transcript TEXT, 
	summary TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, end_reason TEXT, ended_at DATETIME, is_billed BOOLEAN DEFAULT 0 NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE companies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            company_name VARCHAR(200) NOT NULL,
            company_slug VARCHAR(200) NOT NULL UNIQUE,
            balance_minutes INTEGER DEFAULT 20,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        , balance_amount FLOAT DEFAULT 10.0, call_rate FLOAT DEFAULT 0.5);
CREATE TABLE jobs (
	id INTEGER NOT NULL, 
	"jobNO" VARCHAR(50), 
	"bookingId" VARCHAR(50), 
	"passengerName" VARCHAR(200), 
	"customerPrice" VARCHAR(50), 
	date VARCHAR(100), 
	origin VARCHAR(500), 
	destination VARCHAR(500), 
	"vehicleType" VARCHAR(50), 
	call_sid VARCHAR(100), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE vehicle_capacities (
	id INTEGER NOT NULL, 
	vehicle_name VARCHAR(100) NOT NULL, 
	passenger_capacity INTEGER NOT NULL, 
	luggage_capacity INTEGER NOT NULL, 
	hand_luggage_capacity INTEGER, 
	capacity_description VARCHAR(300), 
	PRIMARY KEY (id)
);
CREATE TABLE balance_history (
	id INTEGER NOT NULL, 
	company_id INTEGER NOT NULL, 
	company_slug VARCHAR(200), 
	amount_minutes INTEGER NOT NULL, 
	balance_after INTEGER NOT NULL, 
	note VARCHAR(300), 
	recharged_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE deleted_agents (
	id INTEGER NOT NULL, 
	original_agent_id INTEGER NOT NULL, 
	agent_name VARCHAR(100), 
	company_name VARCHAR(200), 
	company_id INTEGER, 
	company_slug VARCHAR(200), 
	ultravox_agent_id VARCHAR(100), 
	"api_Token" VARCHAR(500), 
	is_active BOOLEAN, 
	created_at DATETIME, 
	deleted_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE web_agents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    agent_name VARCHAR(100) NOT NULL,
    company_name VARCHAR(200),
    company_id INTEGER,
    company_slug VARCHAR(200) NOT NULL,
    greeting_message TEXT,
    custom_prompt TEXT,
    knowledge_base TEXT,
    knowledge_type VARCHAR(20) DEFAULT 'text',
    knowledge_source VARCHAR(500),
    is_active BOOLEAN DEFAULT 1,
    twilio_phone_number VARCHAR(20),
    api_Token VARCHAR(500),
    ultravox_agent_id VARCHAR(100),
    psid VARCHAR(100),
    voice VARCHAR(100),
    web_call_pin INTEGER,
    created_at DATETIME,
    updated_at DATETIME,
    UNIQUE (company_slug)
);
DELETE FROM sqlite_sequence;
CREATE INDEX ix_call_records_agent_id ON call_records (agent_id);
CREATE UNIQUE INDEX ix_call_records_call_sid ON call_records (call_sid);
CREATE INDEX ix_call_records_id ON call_records (id);
CREATE INDEX idx_companies_slug ON companies(company_slug);
CREATE INDEX ix_jobs_call_sid ON jobs (call_sid);
CREATE INDEX ix_jobs_id ON jobs (id);
CREATE UNIQUE INDEX ix_vehicle_capacities_vehicle_name ON vehicle_capacities (vehicle_name);
CREATE INDEX ix_vehicle_capacities_id ON vehicle_capacities (id);
CREATE INDEX ix_balance_history_company_id ON balance_history (company_id);
CREATE INDEX ix_balance_history_id ON balance_history (id);
CREATE INDEX ix_deleted_agents_original_agent_id ON deleted_agents (original_agent_id);
CREATE INDEX ix_deleted_agents_id ON deleted_agents (id);
CREATE INDEX ix_web_agents_id ON web_agents (id);
COMMIT;
